using Godot;
using System;
using System.Linq;
using System.Threading.Tasks;
public partial class MigrationScene {
 int familyCheckAck;
 [Rpc(MultiplayerApi.RpcMode.AnyPeer,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopFamilyCheckAck(int stage){if(coopCheck&&CoopHost&&coopActors.ContainsKey(Multiplayer.GetRemoteSenderId()))familyCheckAck=Math.Max(familyCheckAck,stage);}
 async Task FamilyCoopChecks(CoopActor a){Vector3 home=HostPosition;Teleport(FamilyX,FamilyZ+12);player.Position=FamilyPoint(-3,.1f,-3);a.Body.Position=player.Position+Vector3.Right;EnterDungeon(FamilyDungeon());a.Body.Position=new(0,.1f,-4);SendCoopPersonal(a.Id,CoopProfileJson(a.Game),"",a.Body.Position,true);RpcId(a.Id,nameof(CoopCheckStage),"family-shelf",a.Body.Position);await CoopWait(()=>familyCheckAck>=1,"Guest could not break authored safe-room shelf",20);if(game.World.Changes.FamilyShelfDamage!=54)throw new Exception("Guest shelf damage not authoritative");
  a.Body.Position=new(0,.1f,-6);SendCoopPersonal(a.Id,CoopProfileJson(a.Game),"",a.Body.Position,true);RpcId(a.Id,nameof(CoopCheckStage),"family-door",a.Body.Position);await CoopWait(()=>familyCheckAck>=2,"Guest could not open safe room and defeat frail infected",20);
  a.Body.Position=new(2.2f,.1f,-12);SendCoopPersonal(a.Id,CoopProfileJson(a.Game),"",a.Body.Position,true);RpcId(a.Id,nameof(CoopCheckStage),"family-keys",a.Body.Position);await CoopWait(()=>familyCheckAck>=3,"Guest key pickup did not replicate",15);ExitDungeon();a.Body.Position=FamilyPoint(10,.1f,5);SendCoopPersonal(a.Id,CoopProfileJson(a.Game),"",a.Body.Position,true);RpcId(a.Id,nameof(CoopCheckStage),"family-garage",a.Body.Position);await CoopWait(()=>familyCheckAck>=4,"Guest garage unlock failed",15);
  int hostAmmo=game.Craft.Reserve,guestAmmo=a.Game.Craft.Reserve;a.Body.Position=FamilyPoint(10,.1f,0);SendCoopPersonal(a.Id,CoopProfileJson(a.Game),"",a.Body.Position,true);RpcId(a.Id,nameof(CoopCheckStage),"family-cache",a.Body.Position);await CoopWait(()=>familyCheckAck>=5,"Guest garage rewards did not replicate",15);if(a.Game.Craft.Reserve!=guestAmmo+96||game.Craft.Reserve!=hostAmmo||!game.World.Changes.FamilyGarageClaimed)throw new Exception("Garage reward conservation failed online");Teleport(home.X,home.Z);a.Body.Position=HostPosition+Vector3.Right*3;SendCoopPersonal(a.Id,CoopProfileJson(a.Game),"",a.Body.Position,true);GD.Print("PASS / co-op family basement mapping, guest axe shelf, one-hit surprise, shared keys, garage unlock and personal loot conservation");
 }
 async Task ClientFamilyChecks(string stage,Vector3 target){await CoopWait(()=>Distance(player.Position,target)<1,"Story stage teleport missing",15);if(stage=="family-shelf"){await CoopWait(()=>InFamilyRoom&&GodotObject.IsInstanceValid(familyShelf),"Authored basement replica missing");player.Rotation=Vector3.Zero;pitch=-.32f;camera.Rotation=new(pitch,0,0);await CoopDelay(.4);for(int i=0;i<3;i++){CoopRequest("chop");await CoopDelay(1);}await CoopWait(()=>game.World.Changes.FamilyShelfDamage==54,"Shelf break did not replicate");RpcId(1,nameof(CoopFamilyCheckAck),1);}
  else if(stage=="family-door"){CoopRequest("family","door");await CoopWait(()=>infected.Any(e=>e.Id==FamilyInfectedId&&e.Hp==1),"Frail infected replica missing");player.Rotation=Vector3.Zero;pitch=0;camera.Rotation=Vector3.Zero;await CoopDelay(.7);CoopRequest("shoot");await CoopWait(()=>game.Skills.Defeated.Contains(FamilyInfectedId),"Frail infected did not die in one hit");RpcId(1,nameof(CoopFamilyCheckAck),2);}
  else if(stage=="family-keys"){CoopRequest("family","keys");await CoopWait(()=>game.World.Changes.FamilyKeys,"Shared story keys missing");RpcId(1,nameof(CoopFamilyCheckAck),3);}
  else if(stage=="family-garage"){await CoopWait(()=>dungeon==null&&GodotObject.IsInstanceValid(familyHome),"Surface house replica missing");CoopRequest("family","garage");await CoopWait(()=>game.World.Changes.FamilyGarageOpen,"Garage door state missing");RpcId(1,nameof(CoopFamilyCheckAck),4);}
  else if(stage=="family-cache"){int ammo=game.Craft.Reserve;CoopRequest("family","cache");await CoopWait(()=>game.World.Changes.FamilyGarageClaimed&&game.Craft.Reserve==ammo+96,"Garage loot missing");CoopRequest("family","cache");await CoopDelay(.3);if(game.Craft.Reserve!=ammo+96)throw new Exception("Guest duplicated garage loot");RpcId(1,nameof(CoopFamilyCheckAck),5);}
 }
}
